{
  "questions": [
    {
      "n": 1,
      "start": "Se Lugano Istituti Sociali ha dovuto anticipare e/o rafforzare",
      "end": "le misure proposte dal Medico cantonale"
    },
    {
      "n": 2,
      "start": "A parte le direttive emanate in data 9 marzo 2020",
      "end": "quali altre direttive sono state comunicate alle case anziani?"
    },
    {
      "n": 3,
      "start": "Come mai, durante la pandemia, né il Medico cantonale",
      "end": "si sono accorti del fatto che i decessi (e i contagi) si concentravano"
    },
    {
      "n": 4,
      "start": "Accanto a Lugano istituti sociali vi sono altre strutture",
      "end": "in cui si è proceduto in modo rigoroso a testare il personale e gli ospiti?"
    },
    {
      "n": 5,
      "start": "Quanti sono stati gli ospiti ed il personale",
      "end": "delle case anziani risultati positivi nelle singole settimane"
    },
    {
      "n": 6,
      "start": "In quali case anziani si è potuto beneficiare di un sostegno",
      "end": "da parte di altre strutture sanitarie quali ad esempio gli SPITEX?"
    },
    {
      "n": 7,
      "start": "Corrisponde al vero che ad inizio pandemia lo Stato maggiore",
      "end": "non ha autorizzato l'utilizzo della protezione civile presso le case anziani?"
    },
    {
      "n": 8,
      "start": "Perché i parenti non sono stati coinvolti e consultati",
      "end": "nella scelta delle cure da mettere in atto o non mettere in atto"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "L'osservazione per la quale il LIS ha provveduto a emanare proprie raccomandazioni",
      "end": "non fa altro che confermare che sono le strutture stesse le prime responsabili"
    },
    {
      "n": 2,
      "start": null,
      "end": null
    },
    {
      "n": 3,
      "start": "I decessi per COVID-19 sono notificati al Medico cantonale.",
      "end": "Si era a conoscenza di quali fossero e dove avvenissero"
    },
    {
      "n": 4,
      "start": null,
      "end": null
    },
    {
      "n": 5,
      "start": null,
      "end": null
    },
    {
      "n": 6,
      "start": "A seguito del divieto di entrata del 9 marzo, nessuna struttura ha più potuto fare riferimento",
      "end": "a professionisti esterni. Tutte le strutture hanno tuttavia avuto sostegno da parte dello Stato maggiore"
    },
    {
      "n": 7,
      "start": "No.",
      "end": null
    },
    {
      "n": 8,
      "start": "Laddove i pazienti sono capaci di discernimento essi hanno ovviamente il diritto dell'auto determinazione",
      "end": "e decidono quindi autonomamente."
    }
  ],
  "submitter": "Matteo Pronzini",
  "co_signatories": [],
  "recommendation": "partial",
  "reasoning": {
    "start": "Riteniamo inoltre opportuno fornirvi le seguenti informazioni.",
    "end": "Per quanto possibile, rispondo come segue alle domande."
  }
}
